function subject(p){const b=p.tasks[0].result.body.engineering.binding;return{ownerHash:b.ownerHash,workspaceHash:b.workspaceHash};}
function validate(p){for(const t of p.tasks)eng.validatePersisted(p,t,subject(p));}
function reseal(t){const r=t.result.body.engineering;r.receiptHash=tools.hash({stage:r.stage,binding:r.binding,dependencyRefs:r.dependencyRefs,body:r.body});}
for(const [name,stored]of [['v3',HOSTED_V3],['v1',HOSTED_V1],['nonprofile C3',HOSTED_C3]])test('actual preserved hosted '+name+' remains readable against current fixed source',()=>{a.notEqual(tools.hash(tools.readFile('dashboard.js')),'441484e8a28273bb17eb0c1533b306935c30e00526a5cfc68a8e75b011fad5a6');const p=structuredClone(stored);validate(p);a.deepEqual(p.report.engineering,eng.consolidate(p));a.equal(p.acceptedWork,false);a(p.report.engineering.groups.flatMap(g=>g.findings).every(f=>f.decision==='unresolved'));a.deepEqual(p,stored);});
