function derivedPlan(stored=HOSTED_V3){const monitor=require('../lib/agent-operations-monitoring'),actor={kind:'owner',verifiedOwner:true,id:'history-fixture@example.test',workspaceId:'history-fixture'},old=subject(stored),current={ownerHash:monitor.identity(actor.id),workspaceHash:monitor.identity(actor.workspaceId)};let text=JSON.stringify(stored).replaceAll(old.ownerHash,current.ownerHash).replaceAll(old.workspaceHash,current.workspaceHash),plan=JSON.parse(text);const replacements=[];for(let i=0;i<plan.tasks.length;i++){let t=plan.tasks[i];let value=JSON.stringify(t);for(const [before,after]of replacements)value=value.replaceAll(before,after);t=plan.tasks[i]=JSON.parse(value);const oldResult=tools.hash(stored.tasks[i].result);if(i===4&&t.result.body.engineering.body.artifact.binding){const artifact=t.result.body.engineering.body.artifact;const b=artifact.binding;artifact.patch.proposalHash=tools.hash({version:'draft-proposal-v3',path:'dashboard.js',sourceSha:artifact.sourceSha,preimageSha256:artifact.proposal.beforeSha256,binding:{ownerHash:b.ownerHash,workspaceHash:b.workspaceHash,taskId:b.taskId,sourceCommit:artifact.sourceSha,deploymentId:b.runtime.deploymentId,origin:b.runtime.origin,releaseHash:b.runtime.release.digest,contextHash:tools.hash(b)},edits:artifact.patch.edits});artifact.patchSha256=tools.hash(artifact.patch);}reseal(t);const result=tools.hash(t.result);t.review.resultHash=result;t.attempts.at(-1).resultHash=result;t.attempts.at(-1).reviewHash=tools.hash(t.review);replacements.push([oldResult,result]);}plan.report={acceptedWork:false,internalVerified:true,findings:plan.tasks.map(t=>({taskId:t.id,department:t.department,resultHash:tools.hash(t.result),reviewHash:tools.hash(t.review),qualification:t.result.body.qualification})),businessAcceptance:'not-granted',modelCalls:0,engineering:eng.consolidate(plan)};return{plan,actor,current};}
test('qualified derived owner fixture traverses actual Ops read without historical execution authority',async()=>{const ops=require('../lib/agent-operations-operating-system'),catalog=require('../lib/agent-operations-departments'),{plan,actor,current}=derivedPlan(),state={version:ops.VERSION,catalogVersion:catalog.VERSION,revision:1,...current,plans:[plan,derivedPlan(HOSTED_V1).plan,derivedPlan(HOSTED_C3).plan],incidents:[],audit:[]};a.equal(ops.validate(JSON.stringify(state),actor).plans[0].id,plan.id);let writes=0,authorizations=0;const service=ops.createOperations({kv:{get:async()=>JSON.stringify(state),eval:async()=>{writes++;throw Error('unexpected write');}},ledgerAdapter:{read:async()=>JSON.stringify({version:1,revision:1,tasks:[],reservations:[],operations:{workflows:[],grants:[],reservations:[],audit:[],approvals:[]}})},runtime:{environment:'preview',origin:'https://my-ai-website-historyfixture-mohamtaj004bas-projects.vercel.app',commit:'f'.repeat(40),branch:'feature/callercore-dashboards'},clock:()=>1792044000000,assertOwner:async value=>{authorizations++;return value.id===actor.id&&value.workspaceId===actor.workspaceId;}});const view=await service.read(actor);a.equal(view.plans[0].status,'completed');a.equal(view.plans[0].tasks.length,5);a.equal(view.plans.length,3);a.equal(view.permissions.paidExecution,false);a.equal(writes,0);a(authorizations>=2);});

